import java.util.*;

class Solution {
  public int[] solve(int[] nums, int[][] queries) {
    final long MOD = 1_000_000_007L;
    int n = nums.length, limit = (int) Math.sqrt(n) + 1;
    int[] ans = new int[queries.length];
    // small steps: answer offline with one suffix-sum pass per distinct step; large steps: walk directly
    Map<Integer, List<Integer>> byStep = new HashMap<>();
    for (int i = 0; i < queries.length; i++) {
      int x = queries[i][0], y = queries[i][1];
      if (y < limit) byStep.computeIfAbsent(y, k -> new ArrayList<>()).add(i);
      else {
        long sum = 0;
        for (int j = x; j < n; j += y) sum += nums[j];
        ans[i] = (int) (sum % MOD);
      }
    }
    long[] suffix = new long[n];
    for (Map.Entry<Integer, List<Integer>> e : byStep.entrySet()) {
      int y = e.getKey();
      for (int j = n - 1; j >= 0; j--) suffix[j] = (nums[j] + (j + y < n ? suffix[j + y] : 0)) % MOD;
      for (int qi : e.getValue()) ans[qi] = (int) suffix[queries[qi][0]];
    }
    return ans;
  }
}
